item.command:
"%USERPROFILE%\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$ErrorActionPreference = '"'Continue'
"'$steps = @(
  @{id=1; action='"'git rev-parse HEAD'; run={ git rev-parse HEAD }},
  @{id=2; action='git branch --show-current'; run={ git branch --show-current }},
  @{id=3; action='git --no-optional-locks status --porcelain'; run={ git --no-optional-locks status --porcelain }},
  @{id=4; action='git status --porcelain'; run={ git status --porcelain }},
  @{id=5; action='git log -1 --format=%s'; run={ git log -1 --format=%s }},
  @{id=6; action='git ls-files (count)'; run={ "'$files = git ls-files; ($files | Measure-Object -Line).Lines }},
  @{id=7; action='"'dotnet --version'; run={ dotnet --version }},
  @{id=8; action='Read README.md first line'; run={ Get-Content -LiteralPath README.md -TotalCount 1 }}
)
foreach ("'$s in $steps) {
  try {
    $out = & $s.run 2>&1 | Out-String
    $code = $LASTEXITCODE
    $out = $out.TrimEnd("`r", "`n")
    if ($out.Length -gt 300) { $out = $out.Substring(0,300) }
    [PSCustomObject]@{id=$s.id; action=$s.action; exit_code=$code; output=$out; error=$null} | ConvertTo-Json -Compress -Depth 4
  } catch {
    $msg = $_.Exception.Message
    if ($msg.Length -gt 300) { $msg = $msg.Substring(0,300) }
    [PSCustomObject]@{id=$s.id; action=$s.action; exit_code=$null; output='"''; error="'$msg} | ConvertTo-Json -Compress -Depth 4
  }
}'

